 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); vals={v for row in grid for v in row}
    sep=max(vals,key=lambda v:sum(all(x==v for x in row) for row in grid))
    hr=[r for r in range(h) if all(x==sep for x in grid[r])]
    vc=[c for c in range(w) if all(grid[r][c]==sep for r in range(h))]
    rb=[-1]+hr+[h]; cb=[-1]+vc+[w]
    out=[]
    for i in range(len(rb)-1):
        row=[]
        for j in range(len(cb)-1):
            colors={grid[r][c] for r in range(rb[i]+1,rb[i+1]) for c in range(cb[j]+1,cb[j+1])}
            counts={v:sum(grid[r][c]==v for r in range(rb[i]+1,rb[i+1]) for c in range(cb[j]+1,cb[j+1])) for v in colors}
            rare=[v for v,n in counts.items() if n==1]
            if len(rare)==1:
                majority=max(colors,key=lambda v:counts[v])
                row.append(majority)
            else:
                row.append(1)
        out.append(row)
    return out
